            Parallelism = ParallelismOption.Collections,
            ShadowCopy = false
        });
    },
    "./build/32+64bit/OpenCover/OpenCover.xml",
    new OpenCoverSettings { ReturnTargetCodeOffset = 0, Register = "Path64" }
        .WithFilter("+[SequelMed*]*")
        .WithFilter("-[*]xunit.*"));

    // TODO: Need to think about how to bring this out in a generic way for all Test Frameworks
    ReportGenerator("./build/32+64bit/OpenCover/OpenCover.xml", "./build/32+64bit/OpenCover");
});


```

